using System.Text.Json;
using Westworld.Runtime.Core;
int checks=0;void Check(bool condition,string name){checks++;if(!condition)throw new Exception(name);}
void Reject(Action action,string name){bool rejected=false;try{action();}catch(Exception e) when(e is ArgumentException or InvalidOperationException or ObjectDisposedException){rejected=true;}Check(rejected,name);}
var session=Guid.NewGuid();var actor=Guid.NewGuid();int calls=0;
JsonElement J(string text)=>JsonDocument.Parse(text).RootElement.Clone();
ToolRequest Req(long n,string tool="observe",string args="{}")=>new(session,actor,n,tool,J(args));
ToolBackendResult Backend(string tool,JsonElement args){calls++;return new(true,J("{\"accepted\":true}"));}
var ledger=new ToolCallLedger(session,actor,2);
Check(ledger.NextSequence==1,"initial sequence");
Reject(()=>ledger.Invoke(Req(1) with{SessionId=Guid.NewGuid()},Backend),"session scope");
Reject(()=>ledger.Invoke(Req(1) with{ActorId=Guid.NewGuid()},Backend),"actor scope");
Reject(()=>ledger.Invoke(Req(0),Backend),"zero sequence");Reject(()=>ledger.Invoke(Req(-1),Backend),"negative sequence");Reject(()=>ledger.Invoke(Req(2),Backend),"gap");
Reject(()=>ledger.Invoke(Req(1," "),Backend),"empty tool");Reject(()=>ledger.Invoke(Req(1,new string('a',81)),Backend),"tool bound");Reject(()=>ledger.Invoke(Req(1,args:"[]"),Backend),"object only");Reject(()=>ledger.Invoke(Req(1,args:"{\"x\":\""+new string('a',32768)+"\"}"),Backend),"payload bound");
Check(calls==0&&ledger.NextSequence==1,"invalid admissions no effects");
var first=ledger.Invoke(Req(1,args:"{\"x\":1}"),Backend);Check(first.State=="returned"&&first.Data.GetProperty("accepted").GetBoolean(),"native return not task success");
Check(ReferenceEquals(first,ledger.Invoke(Req(1,args:"{\"x\":1}"),Backend))&&calls==1,"duplicate exact receipt");
Reject(()=>ledger.Invoke(Req(1,"move","{\"x\":1}"),Backend),"tool conflict");Reject(()=>ledger.Invoke(Req(1,args:"{\"x\":2}"),Backend),"argument conflict");Reject(()=>ledger.Invoke(Req(1,args:"{ \"x\":1}"),Backend),"raw whitespace conflict deliberate");
Check(ReferenceEquals(first,ledger.Read(1)),"read receipt");Reject(()=>ledger.Read(2),"unadmitted read");
ledger.Invoke(Req(2),Backend);ledger.Invoke(Req(3),Backend);Reject(()=>ledger.Read(1),"receipt expired");Reject(()=>ledger.Invoke(Req(1,args:"{\"x\":1}"),Backend),"evicted never replayed");Check(calls==3&&ledger.NextSequence==4,"watermark retained after eviction");
var uncertain=ledger.Invoke(Req(4),(_,_)=>{calls++;throw new IOException("private error text");});Check(uncertain.State=="uncertain"&&uncertain.Error=="IOException"&&!uncertain.ToString().Contains("private error text"),"exception sanitized uncertain");
Check(ReferenceEquals(uncertain,ledger.Invoke(Req(4),Backend))&&calls==4,"uncertain duplicate no retry");Check(ledger.NextSequence==5,"uncertain admitted watermark");
Check(ledger.RequiresReconciliation==4,"uncertain hard gate");
Reject(()=>ledger.Invoke(Req(5),Backend),"write blocked before reconcile");Check(ledger.NextSequence==5&&calls==4,"blocked write not admitted");
Reject(()=>ledger.Reconcile(4,3),"old receipt not evidence");
ledger.Invoke(Req(5) with{ReadOnly=true},(_,_)=>new(false,J("null"),"read_failed"));
Reject(()=>ledger.Reconcile(4,5),"failed read not evidence");
ledger.Invoke(Req(6) with{ReadOnly=true},(_,_)=>throw new IOException());
Reject(()=>ledger.Reconcile(4,6),"uncertain read not evidence");Check(ledger.RequiresReconciliation==4,"failed read preserves original gate");
ledger.Invoke(Req(7) with{ReadOnly=true},(_,_)=>new(true,J("{}")));
Reject(()=>ledger.Reconcile(3,7),"wrong uncertain sequence");ledger.Reconcile(4,7);Check(ledger.RequiresReconciliation is null,"successful later read clears gate even evicted original");
Reject(()=>ledger.Reconcile(4,7),"reconcile cannot replay");
Reject(()=>ledger.Invoke(Req(7),Backend),"read classification duplicate conflict");
var error=ledger.Invoke(Req(8),(_,_)=>new(false,J("null"),"busy"));Check(error.State=="native_error"&&error.Error=="busy"&&ledger.RequiresReconciliation==8,"native rejection gates writes");
Reject(()=>ledger.Reconcile(8,7),"pre-error read cannot reconcile new error");
ledger.Invoke(Req(9) with{ReadOnly=true},(_,_)=>new(true,J("{}")));ledger.Reconcile(8,9);
var reentrant=ledger.Invoke(Req(10),(_,_)=>{ledger.Invoke(Req(11),Backend);return new(true,J("null"));});Check(reentrant.State=="uncertain"&&ledger.NextSequence==11&&calls==4,"reentry rejected outer uncertain");
var insideReconcile=ledger.Invoke(Req(11) with{ReadOnly=true},(_,_)=>{ledger.Reconcile(10,9);return new(true,J("{}"));});Check(insideReconcile.State=="uncertain"&&ledger.RequiresReconciliation==10,"reconcile during callback forbidden");
ledger.Invoke(Req(12) with{ReadOnly=true},(_,_)=>new(true,J("{}")));ledger.Reconcile(10,12);
var l2=new ToolCallLedger(session,actor);JsonElement held=default;using(var doc=JsonDocument.Parse("{\"n\":1}")){l2.Invoke(new(session,actor,1,"inspect",doc.RootElement),(_,args)=>{held=args;return new(true,args);});}Check(held.GetProperty("n").GetInt32()==1&&l2.Read(1).Data.GetProperty("n").GetInt32()==1,"request and receipt JSON survive caller disposal");
var l3=new ToolCallLedger(session,actor);var doc2=JsonDocument.Parse("{\"result\":7}");var cloned=l3.Invoke(Req(1),(_,_)=>new(true,doc2.RootElement));doc2.Dispose();Check(cloned.Data.GetProperty("result").GetInt32()==7,"backend data cloned");
Exception? threadError=null;var thread=new Thread(()=>{try{ledger.Invoke(Req(13),Backend);}catch(Exception e){threadError=e;}});thread.Start();thread.Join();Check(threadError is InvalidOperationException&&calls==4,"foreign thread rejects invoke");
threadError=null;thread=new Thread(()=>{try{ledger.Read(12);}catch(Exception e){threadError=e;}});thread.Start();thread.Join();Check(threadError is InvalidOperationException,"foreign thread rejects read");
threadError=null;thread=new Thread(()=>{try{_=ledger.NextSequence;}catch(Exception e){threadError=e;}});thread.Start();thread.Join();Check(threadError is InvalidOperationException,"foreign thread rejects watermark");
var badData=ledger.Invoke(Req(13),(_,_)=>new(true,default));Check(badData.State=="uncertain"&&ledger.NextSequence==14,"malformed backend result may have effects");
threadError=null;thread=new Thread(()=>{try{ledger.Reconcile(13,12);}catch(Exception e){threadError=e;}});thread.Start();thread.Join();Check(threadError is InvalidOperationException,"foreign thread rejects reconcile");
var readOnlyFailure=new ToolCallLedger(session,actor);readOnlyFailure.Invoke(Req(1) with{ReadOnly=true},(_,_)=>throw new IOException());Check(readOnlyFailure.RequiresReconciliation is null,"pure read failure does not bar writes");
var proofEvicted=new ToolCallLedger(session,actor,1);proofEvicted.Invoke(Req(1),(_,_)=>throw new IOException());proofEvicted.Invoke(Req(2) with{ReadOnly=true},(_,_)=>new(true,J("{}")));proofEvicted.Invoke(Req(3) with{ReadOnly=true},(_,_)=>new(true,J("{}")));Reject(()=>proofEvicted.Reconcile(1,2),"evicted evidence cannot reconcile");proofEvicted.Reconcile(1,3);Check(proofEvicted.RequiresReconciliation is null,"latest evidence reconciles");
var stopLedger=new ToolCallLedger(session,actor);int stops=0;
stopLedger.Invoke(Req(1),(_,_)=>throw new IOException());
Reject(()=>stopLedger.Invoke(Req(2) with{ReadOnly=true,StopOnly=true},Backend),"read and stop mutually exclusive");Check(stopLedger.NextSequence==2,"invalid dual mode no admission");
var stopRequest=Req(2,"cancel_action") with{StopOnly=true};
var stopResult=stopLedger.Invoke(stopRequest,(_,_)=>{stops++;return new(true,J("{\"stopped\":true}"));});
Check(stopResult.State=="returned"&&stops==1,"stop admitted through uncertain gate");Check(stopLedger.RequiresReconciliation==1,"successful stop preserves original uncertainty");
Check(ReferenceEquals(stopResult,stopLedger.Invoke(stopRequest,Backend))&&stops==1,"stop duplicate not replayed");
Reject(()=>stopLedger.Invoke(stopRequest with{StopOnly=false},Backend),"stop bit duplicate conflict");
Reject(()=>stopLedger.Reconcile(1,2),"successful stop not read evidence");
Reject(()=>stopLedger.Invoke(Req(3),Backend),"stop does not reopen writes");
stopLedger.Invoke(Req(3) with{ReadOnly=true},(_,_)=>new(true,J("{}")));stopLedger.Reconcile(1,3);Check(stopLedger.RequiresReconciliation is null,"post stop read reconciles");
var failedStop=stopLedger.Invoke(Req(4,"cancel_task") with{StopOnly=true},(_,_)=>new(false,J("null"),"failed"));Check(failedStop.State=="native_error"&&stopLedger.RequiresReconciliation==4,"failed stop sets gate");
var thrownStop=stopLedger.Invoke(Req(5,"cancel_action") with{StopOnly=true},(_,_)=>throw new IOException());Check(thrownStop.State=="uncertain"&&stopLedger.RequiresReconciliation==5,"throwing stop records latest uncertainty");
stopLedger.Invoke(Req(6,"cancel_action") with{StopOnly=true},(_,_)=>new(true,J("{}")));Check(stopLedger.RequiresReconciliation==5,"subsequent successful stop cannot clear error");
Console.WriteLine($"PASS {checks}/{checks}; in-memory protocol only, not crash recovery");
